int key_reject_and_link(struct key *key, unsigned timeout, unsigned error,
                        struct key *keyring, struct key *authkey) {
    int ret;

    if (!key || !keyring) {
        return -EINVAL;
    }

    key_get(key);
    key_get(keyring);

    down_write(&key->sem);

    if (key->type->vtype && key->payload.data) {
        ret = -EEXIST;
        goto error;
    }

    key->flags |= 1 << KEY_FLAG_NEGATIVE;
    key->expiry = jiffies + timeout;
    key->uid = current_uid();
    key->gid = current_gid();

    if (keyring) {
        ret = key_instantiate_and_link(key, NULL, 0, keyring, authkey);
        if (ret < 0)
            goto error;
    }

    key->perm |= KEY_POS_GARBAGE;
    key->usage++;
    key_revoke(authkey);
    key_put(authkey);

    up_write(&key->sem);
    key_put(key);
    key_put(keyring);

    wake_up_interruptible(&key->wait_queue_head);

    return 0;

error:
    key_put(key);
    key_put(keyring);
    up_write(&key->sem);
    return ret;
}

