int key_reject_and_link(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    int ret = 0;

    if (!key || (keyring && !keyring)) {
        return -EINVAL;
    }

    down_write(&key->sem);
    if (key->type->v1.reject) {
        ret = key->type->v1.reject(key, error, authkey);
        if (ret < 0) {
            up_write(&key->sem);
            return ret;
        }
    }

    key->flags |= 1 << (KEY_FLAG_INstantiated - 1);
    key->expiry = get_seconds() + timeout;
    key_schedule_gc(key->expiry, key);

    if (keyring) {
        ret = key_link(keyring, key);
        if (ret < 0) {
            up_write(&key->sem);
            return ret;
        }

        key_revoke(authkey);
    }

    up_write(&key->sem);
    key_notify(key, 0, 0);

    return 0;
}

int reject_key_and_link(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    int ret = 0;

    if (!key || !keyring) {
        return -EINVAL;
    }

    /* Ensure the key is not already instantiated */
    if (key->type->v1.instantiate && key->type->v1.instantiate(key, NULL, NULL)) {
        return -EINVAL;
    }

    /* Mark the key as negatively instantiated with the provided error */
    key->error = error;
    key->flags |= 1 << (KEY_FLAG_NEGATIVE_INSTANTIATED - 1);

    /* Set the key's expiry time */
    key->expiry = jiffies + timeout * HZ;

    /* Schedule garbage collection if necessary */
    key_schedule_gc(key);

    if (keyring) {
        /* Link the key to the keyring */
        ret = key_link(keyring, key);
        if (ret < 0) {
            return ret;
        }

        /* Revoke the authorization key if provided */
        if (authkey) {
            key_revoke(authkey);
        }
    }

    /* Wake up any waiting processes if the key was constructed */
    if (key->wait_queue) {
        wake_up(key->wait_queue);
    }

    return 0;
}

int reject_key_and_link_to_keyring(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    if (!key || !keyring) {
        return -EINVAL;
    }

    if (key->instanced) {
        return -EEXIST;
    }

    key->negative = 1;
    key->expiry = get_current_time() + timeout;
    key->error = error;

    if (keyring) {
        if (link_key_to_keyring(key, keyring) < 0) {
            return -ENOKEY;
        }
    }

    if (authkey) {
        revoke_authorization_key(authkey);
    }

    schedule_key_garbage_collection();

    if (key->constructed) {
        wake_up_key_waiters(key);
    }

    return 0;
}
